<script setup>
import { nextTick, ref } from 'vue';
const priorities = ['Low', 'Medium', 'High'];
const makeTasks = (count) => Array.from({ length: count }, (_, index) => ({ id: index + 1, name: `Task ${index + 1}`, priority: priorities[index % priorities.length] }));
const tasks = ref([]); const newName = ref(''); const newPriority = ref('Medium');
const editingId = ref(null); const editName = ref(''); const editPriority = ref('Medium');
const results = ref([]); const message = ref(''); const busy = ref(false);
function addTask() { const name = newName.value.trim(); if (!name) return; tasks.value.push({ id: Date.now() + Math.random(), name, priority: newPriority.value }); newName.value = ''; }
function startEdit(task) { editingId.value = task.id; editName.value = task.name; editPriority.value = task.priority; }
function saveEdit(task) { const name = editName.value.trim(); if (!name) return; task.name = name; task.priority = editPriority.value; editingId.value = null; }
function deleteTask(id) { tasks.value = tasks.value.filter((task) => task.id !== id); }
const nextFrame = () => new Promise((resolve) => requestAnimationFrame(resolve));
async function settle() { await nextTick(); await nextFrame(); }
function record(label, start) { const ms = Number((performance.now() - start).toFixed(3)); results.value.push({ label, ms, time: new Date().toLocaleTimeString() }); }
async function timedRender(count) { tasks.value = []; await settle(); const start = performance.now(); tasks.value = makeTasks(count); await settle(); record(`Initial render — ${count} tasks`, start); }
async function runSuite() { if (busy.value) return; busy.value = true; message.value = 'Running benchmark suite…'; try { for (const count of [100, 500, 1000]) await timedRender(count); const startUpdate = performance.now(); tasks.value = tasks.value.map((task, index) => index < 50 ? { ...task, name: `${task.name} *`, priority: priorities[(priorities.indexOf(task.priority) + 1) % priorities.length] } : task); await settle(); record('Update 50 tasks (from 1,000)', startUpdate); const startDelete = performance.now(); tasks.value = tasks.value.filter((_, index) => index >= 50); await settle(); record('Delete 50 tasks (from 1,000)', startDelete); message.value = 'Suite finished. Repeat at least five times and use the median.'; } catch (error) { message.value = `Benchmark failed: ${String(error)}`; } finally { busy.value = false; } }
function downloadCsv() { const rows = [['operation','milliseconds','recorded_at'], ...results.value.map((item) => [item.label,item.ms,item.time])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"','""')}"`).join(',')).join('\n'); const url = URL.createObjectURL(new Blob([csv], { type:'text/csv;charset=utf-8;' })); const link = document.createElement('a'); link.href = url; link.download = 'vue-benchmark-results.csv'; link.click(); URL.revokeObjectURL(url); }
</script>
<template><main class="page"><header><p class="eyebrow">DOM PERFORMANCE LAB · VUE</p><h1>Task Tracker</h1><p class="subtitle">Add, edit, prioritize, and delete tasks. Run the same DOM workload used in the other framework apps.</p></header>
<section class="panel"><h2>Add a task</h2><form class="add-form" @submit.prevent="addTask"><label>Task name<input v-model="newName" placeholder="e.g. Review assignment" /></label><label>Priority<select v-model="newPriority"><option v-for="priority in priorities" :key="priority">{{ priority }}</option></select></label><button type="submit">Add task</button></form></section>
<section class="panel"><div class="section-heading"><h2>Tasks <span class="count">{{ tasks.length }}</span></h2><button class="secondary" @click="tasks = []">Clear all</button></div><p v-if="tasks.length === 0" class="empty">No tasks yet. Add one above or run the benchmark suite.</p><ul v-else class="task-list"><li v-for="task in tasks" :key="task.id" class="task-row"><template v-if="editingId === task.id"><div class="edit-fields"><input v-model="editName" aria-label="Edit task name"/><select v-model="editPriority" aria-label="Edit priority"><option v-for="priority in priorities" :key="priority">{{ priority }}</option></select><button @click="saveEdit(task)">Save</button><button class="secondary" @click="editingId = null">Cancel</button></div></template><template v-else><div class="task-text"><span>{{ task.name }}</span><span class="priority" :class="task.priority.toLowerCase()">{{ task.priority }}</span></div><div class="task-actions"><button class="secondary" @click="startEdit(task)">Edit</button><button class="danger" @click="deleteTask(task.id)">Delete</button></div></template></li></ul></section>
<section class="panel benchmark"><div class="section-heading"><div><p class="eyebrow">REPEATABLE WORKLOAD</p><h2>DOM benchmark</h2></div><button :disabled="busy" @click="runSuite">{{ busy ? 'Running…' : 'Run benchmark suite' }}</button></div><p class="muted">Renders 100, 500, and 1,000 tasks from empty; updates 50 tasks; then deletes 50 tasks from the 1,000-task list.</p><p v-if="message" class="status" role="status">{{ message }}</p><template v-if="results.length"><div class="table-wrap"><table><thead><tr><th>Operation</th><th>Time (ms)</th><th>Recorded</th></tr></thead><tbody><tr v-for="(item,index) in results" :key="`${item.label}-${index}`"><td>{{ item.label }}</td><td>{{ item.ms.toFixed(3) }}</td><td>{{ item.time }}</td></tr></tbody></table></div><div class="result-actions"><button class="secondary" @click="downloadCsv">Download CSV</button><button class="secondary" @click="results = []">Clear results</button></div></template><p v-else class="empty">No measurements yet.</p></section><footer>Browser timings are approximate. Run at least five suites in the same environment and compare medians.</footer></main></template>
